files.templates/support-triage-assistant/TEMPL:
{
  "schema_version": 1,
  "template_id": "support-triage-assistant",
  "template_version": 2,
  "checks": [
    {
      "id": "identity",
      "title": "Confirm support role and owner",
      "instructions": "Confirm whether Support Triage Assistant is this Crew’s primary role or an added capability. Preserve existing Crew identity and name the case or feedback owner."
    },
    {
      "id": "skill",
      "title": "Verify the selected skill",
      "instructions": "Confirm skills/support-triage-assistant/SKILL.md exists and support-triage-assistant is selected for this Crew."
    },
    {
      "id": "scope",
      "title": "Set case and customer scope",
      "instructions": "Record product, support channel, customer and case identity, time zone, privacy boundary, owner, and first job. Minimum input: Support inbox or case export, service and priority policy, product scope, customer identity rule, response deadlines, and triage owner."
    },
    {
      "id": "access",
      "title": "Prove the role-specific source join",
      "instructions": "Read one current case thread, its status and prior replies, the proposed duplicate case, and the active priority/SLA policy. Record exact case IDs, account join, observation times, rule version and timezone. An incident claim requires a separate current incident source. Helpdesk such as Zendesk or Intercom, shared inbox, product status, CRM account view, and issue tracker when authorized; an export supports a first read-only queue."
    },
    {
      "id": "policy",
      "title": "Verify the role-specific acceptance rule",
      "instructions": "Reproduce the priority and first-response deadline from the policy and case timestamps. Demonstrate that a shared symptom without an account or issue join is not silently merged, and that an unverified incident remains unverified. Record the customer policy revision and accountable review owner. Unknown stays unknown."
    },
    {
      "id": "first_result",
      "title": "Produce a first sourced result",
      "instructions": "Use real authorized records to produce A case queue with stable IDs, customer and channel scope, issue summary, priority rationale, duplicate state, response deadline, owner, and next evidence. Every urgency and duplicate claim needs case IDs, observed times, policy rule, and supporting source references. A fictional example does not complete this check."
    },
    {
      "id": "review",
      "title": "Review the case or feedback result",
      "instructions": "Show exact source links, unknowns, owner, proposed next action, and any customer-facing draft. Record owner corrections and approval decision."
    },
    {
      "id": "delivery",
      "title": "Choose case and message routes",
      "optional": true,
      "instructions": "Choose read-only chat or separately authorized ticket updates, escalation, and message delivery. Read-only chat completes this choice. Do not change priority, assign a case, merge tickets, contact a customer, or declare an incident without the authorized route and owner review."
    },
    {
      "id": "recurrence",
      "title": "Choose repeat and Automation route",
      "optional": true,
      "instructions": "Choose manual-only or a reviewed authenticated event or schedule with stable IDs and deduplication. Manual-only completes this choice. Reconcile the same case IDs, status and prior replies; add only new evidence, do not reopen resolved cases or create duplicate owner alerts."
    }
  ],
  "completed_steps": []
}

