    },
    {
      "id": "first_result",
      "title": "Produce a first sourced result",
      "instructions": "Use real authorized records to produce An unsent reply draft with exact case and recipient reference, approved source citations, issue-specific steps, unknowns, owner review, and next-check rule. A plausible answer is insufficient without current article or account references and a check that the draft addresses the latest case state. A fictional example does not complete this check."
    },
    {
      "id": "review",
      "title": "Review the case or feedback result",
      "instructions": "Show exact source links, unknowns, owner, proposed next action, and any customer-facing draft. Record owner corrections and approval decision."
    },
    {
      "id": "delivery",
      "title": "Choose case and message routes",
      "optional": true,
      "instructions": "Choose read-only chat or separately authorized ticket updates, escalation, and message delivery. Read-only chat completes this choice. Do not send, promise a refund or fix date, disclose another customer’s data, change the ticket, or run account actions from a draft."
    },
    {
      "id": "recurrence",
      "title": "Choose repeat and Automation route",
      "optional": true,
      "instructions": "Choose manual-only or a reviewed authenticated event or schedule with stable IDs and deduplication. Manual-only completes this choice. Re-read the case thread, prior send receipts, and knowledge revision before another draft; stop when the customer replied, the case resolved, or contact policy changed."
    }
  ],
  "completed_steps": []
}

