      "id": "identity",
      "title": "Confirm support role and owner",
      "instructions": "Confirm whether Feedback & Review Analyst is this Crew’s primary role or an added capability. Preserve existing Crew identity and name the case or feedback owner."
    },
    {
      "id": "skill",
      "title": "Verify the selected skill",
      "instructions": "Confirm skills/feedback-review-analyst/SKILL.md exists and feedback-review-analyst is selected for this Crew."
