    {
      "id": "scope",
      "title": "Set case and customer scope",
      "instructions": "Record product, support channel, customer and case identity, time zone, privacy boundary, owner, and first job. Minimum input: Review or feedback export, product and period scope, channel policy, response owner, sensitive-data rules, and theme decision criteria."
    },
    {
      "id": "access",
      "title": "Prove the role-specific source join",
      "instructions": "Read one bounded feedback export with source IDs, response coverage, period and segment; join a linked support case by exact ID and inspect the current product issue before claiming a match. Record unique reporters, total mentions and excluded duplicate IDs. Helpdesk tags, survey or review platforms, product issue tracker, CRM segments, and approved public reply channel; exports support read-only analysis."
    },
    {
      "id": "policy",
      "title": "Verify the role-specific acceptance rule",
      "instructions": "Recalculate one theme numerator and its source-specific denominator, show a duplicate and an excluded record, and apply the quotation/privacy policy. A public reply stays unsent; a small or partial sample cannot become a population-wide trend. Record the customer policy revision and accountable review owner. Unknown stays unknown."
    },
    {
      "id": "first_result",
      "title": "Produce a first sourced result",
      "instructions": "Use real authorized records to produce A feedback brief with deduplicated source IDs, theme and affected segment, volume with denominator, representative quotes or paraphrases, owner, and reviewable next action. A theme needs representative source IDs, volume and denominator, period, and limits; one loud review is not a population-wide trend. A fictional example does not complete this check."
    },
    {
      "id": "review",
      "title": "Review the case or feedback result",
      "instructions": "Show exact source links, unknowns, owner, proposed next action, and any customer-facing draft. Record owner corrections and approval decision."
    },
    {
      "id": "delivery",
      "title": "Choose case and message routes",
      "optional": true,
      "instructions": "Choose read-only chat or separately authorized ticket updates, escalation, and message delivery. Read-only chat completes this choice. Do not publish a review reply, delete feedback, change a product issue, expose customer identity, or claim a trend without review and observed source coverage."
    },
    {
      "id": "recurrence",
      "title": "Choose repeat and Automation route",
      "optional": true,
      "instructions": "Choose manual-only or a reviewed authenticated event or schedule with stable IDs and deduplication. Manual-only completes this choice. Keep stable theme and feedback IDs, compare like periods and source coverage, carry unresolved owner actions, and avoid replying twice to the same review."
    }
  ],
  "completed_steps": []
}
